import React, { useContext } from "react";
import noteContext from "../context/notes/noteContext";

const SearchAndFilter = () => {
  const context = useContext(noteContext);
  const { 
    searchTerm, 
    setSearchTerm, 
    selectedTag, 
    setSelectedTag, 
    sortBy, 
    setSortBy, 
    getAllTags 
  } = context;

  const availableTags = getAllTags();

  const clearFilters = () => {
    setSearchTerm("");
    setSelectedTag("");
    setSortBy("dateCreated");
  };

  return (
    <div className="card mb-4">
      <div className="card-header">
        <h5 className="mb-0">
          <i className="fas fa-search me-2"></i>Search & Filter
        </h5>
      </div>
      <div className="card-body">
        <div className="row g-3">
          {/* Search Input */}
          <div className="col-md-4">
            <label htmlFor="searchInput" className="form-label">
              <i className="fas fa-search me-1"></i>Search Notes
            </label>
            <div className="input-group">
              <input
                type="text"
                className="form-control"
                id="searchInput"
                placeholder="Search by title, content, or tags..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
              {searchTerm && (
                <button
                  className="btn btn-outline-secondary"
                  type="button"
                  onClick={() => setSearchTerm("")}
                  title="Clear search"
                >
                  <i className="fas fa-times"></i>
                </button>
              )}
            </div>
          </div>

          {/* Tag Filter */}
          <div className="col-md-4">
            <label htmlFor="tagFilter" className="form-label">
              <i className="fas fa-tag me-1"></i>Filter by Tag
            </label>
            <select
              className="form-select"
              id="tagFilter"
              value={selectedTag}
              onChange={(e) => setSelectedTag(e.target.value)}
            >
              <option value="">All Tags</option>
              {availableTags.map((tag, index) => (
                <option key={index} value={tag}>
                  {tag}
                </option>
              ))}
            </select>
          </div>

          {/* Sort Options */}
          <div className="col-md-4">
            <label htmlFor="sortSelect" className="form-label">
              <i className="fas fa-sort me-1"></i>Sort By
            </label>
            <select
              className="form-select"
              id="sortSelect"
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value)}
            >
              <option value="dateCreated">Date Created (Newest First)</option>
              <option value="dateModified">Date Modified (Newest First)</option>
              <option value="alphabetical">Title (A-Z)</option>
              <option value="alphabeticalDesc">Title (Z-A)</option>
            </select>
          </div>
        </div>

        {/* Filter Summary and Clear Button */}
        <div className="row mt-3">
          <div className="col-12">
            <div className="d-flex justify-content-between align-items-center">
              <div className="text-muted small">
                {(searchTerm || selectedTag) && (
                  <>
                    Active filters: 
                    {searchTerm && (
                      <span className="badge bg-primary ms-1 me-1">
                        Search: "{searchTerm}"
                      </span>
                    )}
                    {selectedTag && (
                      <span className="badge bg-info ms-1 me-1">
                        Tag: {selectedTag}
                      </span>
                    )}
                  </>
                )}
              </div>
              {(searchTerm || selectedTag || sortBy !== "dateCreated") && (
                <button
                  className="btn btn-outline-secondary btn-sm"
                  onClick={clearFilters}
                >
                  <i className="fas fa-times me-1"></i>Clear All Filters
                </button>
              )}
            </div>
          </div>
        </div>

        {/* Quick Tag Filters */}
        {availableTags.length > 0 && (
          <div className="row mt-3">
            <div className="col-12">
              <small className="text-muted">Quick tag filters:</small>
              <div className="mt-1">
                {availableTags.slice(0, 6).map((tag, index) => (
                  <button
                    key={index}
                    className={`btn btn-sm me-1 mb-1 ${
                      selectedTag === tag 
                        ? 'btn-primary' 
                        : 'btn-outline-primary'
                    }`}
                    onClick={() => setSelectedTag(selectedTag === tag ? "" : tag)}
                  >
                    {tag}
                  </button>
                ))}
                {availableTags.length > 6 && (
                  <small className="text-muted">
                    +{availableTags.length - 6} more tags
                  </small>
                )}
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default SearchAndFilter;
